export function validateWalkParameters(input){if(!input||Array.isArray(input)||typeof input!=='object')throw Error('Choose a walking preset');const p=structuredClone(meshWalkDefaults);for(const[k,v]of Object.entries(input))if(k in p)p[k]=structuredClone(v);for(const[k,v]of Object.entries(meshWalkDefaults))if(typeof v==='number'&&!Number.isFinite(p[k]))throw Error('Use a finite number for '+k);for(const[key,min,max]of [['walkCycleRate',.05,4],['walkStance',.25,.95],['walkThighLength',1,1000],['walkShinLength',1,1000],['walkBodyWidth',.05,5],['walkLimbWidth',.05,5],['walkFootSize',.05,5],['walkHeadSize',.05,5]])if(p[key]<min||p[key]>max)throw Error(key+' is outside its supported range');for(const[key,min,max]of [['walkMeshColumns',2,18],['walkMeshRows',3,28]])if(!Number.isInteger(p[key])||p[key]<min||p[key]>max)throw Error(key+' must be a whole number from '+min+' to '+max);if(!['walk','idle','pose'].includes(p.walkMode))throw Error('Choose Walking, Standing or Pose');if(![-1,1].includes(p.walkFacing))throw Error('Facing must be1 or-1');for(const v of Object.values(p.walkJointOffsets||{}))if(!Array.isArray(v)||v.length!==2||!v.every(Number.isFinite))throw Error('Joint offsets need two finite coordinates');for(const r of Object.values(p.walkPartRects||{}))if(!Array.isArray(r)||r.length!==4||!r.every(Number.isFinite)||r[2]<=0||r[3]<=0)throw Error('Part source rectangles need positive width and height');for(const a of Object.values(p.walkPartAnchors||{})){for(const k of ['start','end'])if(!Array.isArray(a[k])||a[k].length!==2||!a[k].every(v=>Number.isFinite(v)&&v>=0&&v<=1))throw Error('Attachment points must lie inside the source');if(Math.hypot(a.start[0]-a.end[0],a.start[1]-a.end[1])<.001)throw Error('Start and end attachment points must differ');}return p;}
